const el = document.getElementById('container');
const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
canvas.width = el.offsetWidth || 400; canvas.height = el.offsetHeight || 500;
el.appendChild(canvas);

const W = canvas.width, H = canvas.height;
let mouse = { x: null, y: null };
const particles = [];

for(let i=0; i<60; i++) {
  particles.push({
    x: Math.random() * W, y: Math.random() * H,
    vx: (Math.random() - 0.5), vy: (Math.random() - 0.5),
    size: Math.random() * 2 + 1
  });
}

el.addEventListener('pointermove', (e) => {
  const rect = el.getBoundingClientRect();
  mouse.x = e.clientX - rect.left; mouse.y = e.clientY - rect.top;
});
el.addEventListener('pointerleave', () => { mouse.x = null; mouse.y = null; });

function draw() {
  ctx.clearRect(0, 0, W, H);

  particles.forEach(p => {
    p.x += p.vx; p.y += p.vy;
    if(p.x < 0 || p.x > W) p.vx *= -1;
    if(p.y < 0 || p.y > H) p.vy *= -1;

    ctx.fillStyle = '#ff007f';
    ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2); ctx.fill();

    // Connect particles
    particles.forEach(p2 => {
      const dist = Math.hypot(p.x - p2.x, p.y - p2.y);
      if(dist < 80) {
        ctx.strokeStyle = `rgba(0, 255, 204, ${1 - dist/80})`;
        ctx.lineWidth = 0.5;
        ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
      }
    });

    // Connect to mouse
    if(mouse.x != null) {
      const mDist = Math.hypot(p.x - mouse.x, p.y - mouse.y);
      if(mDist < 120) {
        ctx.strokeStyle = `rgba(255, 0, 127, ${1 - mDist/120})`;
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(mouse.x, mouse.y); ctx.stroke();
      }
    }
  });
  requestAnimationFrame(draw);
}
draw();
